const initial=()=>({active:'home',sidebar:true,collapsedNav:{'产业岗位调研':true,'专业群能力图谱':true,'培养方案与课程大纲':true,'供需匹配':true,'调研报告':true},selectedPosition:'p1',selectedCourse:'c1',graphTab:'图谱',demandTab:'全部',reportTab:'我的报告',notice:'',editingReport:'r1',reportContent:'', planDraft:{}, node:'', modal:null});
function loadData(){try{const s=JSON.parse(localStorage.getItem('nm-demo-data'));if(s)return s}catch(e){}return structuredClone(I)}
let D=loadData(),S=initial();
function persist(){localStorage.setItem('nm-demo-data',JSON.stringify(D))}
function el(id){return document.getElementById(id)}
function safe(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function allNav(){return NAV.flatMap(g=>g.items)}
function getTitle(id){return allNav().find(x=>x[0]===id)?.[2]||({home:'平台总览','plan-preview':'培养方案预览','jobdetail':'岗位溯源','company':'企业详情','standard-edit':'课程标准编制','plan-new':'新增培养方案','template-edit':'AI报告模板配置','report-edit':'产业链报告编辑器','doc-preview':'知识库资料预览','admin-nav':'管理员菜单'}[id]||id)}
function go(id){if(!FEATURE_IDS.includes(id))id='home';S.active=id;let g=NAV.find(x=>x.items.some(item=>item[0]===id));if(g)S.collapsedNav[g.group]=false;location.hash=id;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{let h=location.hash.slice(1);if(h&&S.active!==h){S.active=FEATURE_IDS.includes(h)?h:'home';render()}});
function toast(s){const t=el('toast');t.textContent=s;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2300)}
function btn(label,action,kind=''){return `<button class="btn ${kind}" data-action="${action}">${label}</button>`}
function stat(label,value,symbol='◈',delta=''){return `<div class="stat"><div class="stat-top"><span>${label}</span><i class="symbol">${symbol}</i></div><strong>${value}</strong>${delta?`<em>${delta}</em>`:''}</div>`}
function card(title,content,extra=''){return `<section class="card"><div class="card-title">${title}${extra?`<small>${extra}</small>`:''}</div>${content}</section>`}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">暂无数据</td></tr>`}</tbody></table></div>`}
function tag(text,type=''){return `<span class="tag ${type}">${safe(text)}</span>`}
function row(cells){return `<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`}
function headActions(){let a='';if(S.active==='home')a=btn('刷新数据','refresh');else if(['reports','plans','library'].includes(S.active))a=btn('新建','new','primary');else if(S.active==='demand')a=btn('提交需求','new','primary');else a=btn('重置筛选','reset-filter');return a}
function shell(){let active=S.active;return `<div class="shell"><header class="topbar"><button class="btn" style="padding:5px 9px" data-action="sidebar">☰</button><div class="brandmark">图</div><div class="brand">专业群能力图谱平台<small>${I.schools}</small></div><span class="demo-pill">演示环境 · 数据为模拟数据</span><div class="top-spacer"></div><button class="user" data-action="admin"><span class="avatar">管</span><span>管理员<small style="display:block;color:#9aa4b4;font-size:10px;font-weight:400">${I.schools}</small></span>⌄</button></header><div class="layout">${S.sidebar?`<aside class="sidebar">${NAV.map(g=>`<button class="nav-label" aria-expanded="${!S.collapsedNav[g.group]}" data-action="toggle-nav-group" data-value="${g.group}"><span>${g.group}</span><span class="nav-caret">${S.collapsedNav[g.group]?'＋':'−'}</span></button>${S.collapsedNav[g.group]?'':g.items.map(([id,ic,n])=>`<button class="nav-item ${id===active?'active':''}" data-route="${id}" title="${n}"><span class="nav-icon">${ic}</span><span>${n}</span></button>`).join('')}`).join('')}<div class="side-foot">● 数据服务运行正常<br>演示数据版本 · 2026.11</div></aside>`:''}<main class="main"><div class="crumb">首页　›　${active==='home'?'工作台':getTitle(active)}</div><div class="page-head"><div><h1>${getTitle(active)}</h1><div class="subtitle">${subtitles[active]||'查看和管理专业群能力建设相关信息'} <span class="tag orange">演示数据</span></div></div><div class="head-actions">${headActions()}</div></div><div id="content">${page()}</div></main></div>${S.modal?modal():''}</div>`}
const subtitles={home:'产业、岗位与专业能力建设全景',chain:'查看产业链环节与关联企业，继续追踪岗位需求',graph:'从产业链到专业课程，查看能力培养关系',supply:'对照企业人才需求与专业群培养供给',reports:'基于岗位与专业数据形成调研报告'};
function render(){el('app').innerHTML=S.active==='login'?loginPage():shell();bind()}
function loginPage(){return `<div style="min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 20% 20%,#e7f0ff,#f5f7fb 50%,#e6f5f1)"><div class="card" style="width:min(420px,calc(100% - 32px));padding:32px"><div style="display:flex;align-items:center;gap:12px"><div class="brandmark" style="width:42px;height:42px">图</div><div><b>专业群能力图谱平台</b><div class="subtitle">${I.schools}</div></div></div><h2 style="margin:28px 0 4px">欢迎登录</h2><p class="subtitle">登录后查看专业群产业能力建设情况</p><div class="field" style="margin-top:20px"><label>账号</label><input id="login-user" value="admin"></div><div class="field" style="margin-top:12px"><label>密码</label><input id="login-pass" type="password" value="demo123"></div><label class="subtitle" style="display:flex;align-items:center;gap:7px;margin:12px 0"><input type="checkbox" checked> 保持登录状态</label><button class="btn primary" style="width:100%;padding:11px" data-action="login-submit">登录演示平台</button><div class="notice">演示账号：admin　密码：demo123</div></div></div>`}
function page(){switch(S.active){
case'home':return home();case'chain':return chain();case'insight':return insight();case'jobs':return jobs();case'jobdetail':return jobDetail();case'company':return company();case'portrait':return portrait();case'fourmap':return fourmap();case'graph':case'skills':case'network':return graphPage();case'course-jobs':return courseJobs();case'recommend':return recommend();case'portal':return portal();case'supply':return supply();case'demand':return demand();case'plans':return plans();case'plan-new':return planNew();case'plan-preview':return planPreview();case'versions':return versions();case'standards':return standards();case'standard-edit':return standardEdit();case'library':case'doc-preview':return library();case'reports':return reports();case'report-edit':return reportEdit();case'templates':case'template-edit':return templates();case'forecast':return forecast();case'emerging':return emerging();case'news':return news();case'matrix-types':case'major-jobs':case'embed':case'tasks':case'research':case'plan-config':case'review':return lightPage();default:return lightPage();}}
function home(){
 let demand=D.requirements.filter(x=>x.status==='\u5df2\u901a\u8fc7').reduce((n,x)=>n+x.count,0);
 let stats=`${stat('\u5173\u8054\u4f01\u4e1a',D.companies.length,'\u25a3')}${stat('\u76d1\u6d4b\u5c97\u4f4d',D.positions.length,'\u25a4')}${stat('\u5c97\u4f4d\u7fa4',new Set(D.positions.map(x=>x.group)).size,'\u25c9')}${stat('\u80fd\u529b\u56fe\u8c31\u8282\u70b9',D.positions.reduce((n,p)=>n+p.skills.length,0)+D.courses.length,'\u2318')}${stat('\u8bfe\u7a0b\u6807\u51c6',D.courses.length,'\u25a5')}${stat('\u57f9\u517b\u65b9\u6848',D.plans.length,'\u25a7')}${stat('\u4f01\u4e1a\u9700\u6c42\u4eba\u6570',demand,'\u2197')}${stat('\u62a5\u544a',D.reports.length,'\u25a4')}`;
 let modules=[['chain','\u4ea7\u4e1a\u94fe\u5168\u666f','\u67e5\u770b\u4ea7\u4e1a\u73af\u8282\u4e0e\u5173\u8054\u4f01\u4e1a'],['jobs','\u5c97\u4f4d\u5e93','\u68c0\u7d22\u533a\u57df\u5c97\u4f4d\u9700\u6c42'],['graph','\u4e13\u4e1a\u7fa4\u80fd\u529b\u56fe\u8c31','\u6d4f\u89c8\u4ea7\u4e1a\u5230\u8bfe\u7a0b\u7684\u80fd\u529b\u6620\u5c04'],['plans','\u57f9\u517b\u65b9\u6848\u7ba1\u7406','\u67e5\u770b\u65b9\u6848\u4e0e\u7248\u672c\u5dee\u5f02'],['supply','\u4f9b\u9700\u5339\u914d\u770b\u677f','\u5b9a\u4f4d\u4eba\u624d\u4f9b\u9700\u4e0e\u80fd\u529b\u7f3a\u53e3'],['reports','\u4ea7\u4e1a\u94fe\u6d1e\u5bdf\u62a5\u544a','\u67e5\u770b\u4e0e\u7f16\u5236\u8c03\u7814\u62a5\u544a']].map(x=>`<div class="card module-card" data-route="${x[0]}"><span class="tag">${x[1]}</span><strong>${x[2]}</strong><p>\u8fdb\u5165\u6a21\u5757 \u2192</p></div>`).join('');
 return `<div class="stats">${stats}</div>${card('\u4ea7\u4e1a\u5c97\u4f4d\u9700\u6c42\u8d8b\u52bf',lineChart(['2022','2023','2024','2025','2026'],[28,43,52,68,82]),'\u62db\u8058\u9700\u6c42\u6307\u6570 \u00b7 \u793a\u4f8b')}${card('\u4e1a\u52a1\u6a21\u5757\u5165\u53e3',`<div class="grid3">${modules}</div>`)}`;
}
function bars(labels,vals,green=false){let max=Math.max(...vals);return `<div class="bars">${labels.map((l,i)=>`<div class="bar-col"><span class="bar-val">${vals[i]}</span><i class="bar ${green?'green':''}" style="height:${Math.max(12,vals[i]/max*100)}%"></i><span>${l}</span></div>`).join('')}</div>`}
function lineChart(labels,values){let w=900,h=245,p={l:46,r:20,t:24,b:35},max=Math.ceil(Math.max(...values)/20)*20,min=0,x=i=>p.l+i*(w-p.l-p.r)/(labels.length-1),y=v=>p.t+(max-v)*(h-p.t-p.b)/(max-min),pts=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<div class="line-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="年度产业岗位需求趋势折线图"><defs><linearGradient id="line-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3777ed" stop-opacity=".19"/><stop offset="1" stop-color="#3777ed" stop-opacity="0"/></linearGradient></defs>${[0,20,40,60,80,100].filter(v=>v<=max).map(v=>`<line x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}" stroke="#e9eef5" stroke-width="1"/><text x="${p.l-12}" y="${y(v)+4}" text-anchor="end" fill="#96a1b2" font-size="11">${v}</text>`).join('')}<polygon points="${x(0)},${h-p.b} ${pts} ${x(labels.length-1)},${h-p.b}" fill="url(#line-fill)"/><polyline points="${pts}" fill="none" stroke="#3777ed" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="5" fill="#fff" stroke="#3777ed" stroke-width="3"><title>${labels[i]}：${v}</title></circle><text x="${x(i)}" y="${y(v)-12}" text-anchor="middle" fill="#53617a" font-size="11">${v}</text><text x="${x(i)}" y="${h-9}" text-anchor="middle" fill="#8490a3" font-size="11">${labels[i]}</text>`).join('')}</svg></div>`}
function chain(){return `<div class="filters"><div class="field"><label>区域</label><select><option>内蒙古自治区</option><option>呼和浩特市</option></select></div><div class="field"><label>产业链</label><select><option>${I.industry}</option><option>新能源装备制造</option></select></div></div><div class="grid3">${[['上游','设备与能源供应','设备制造、能源供应及工程材料',3],['中游','工程建设与系统集成','设计施工、设备安装与系统集成',2],['下游','城市运行与设施维护','供热、供水、楼宇与安全运维',4]].map((x,i)=>`<div class="card module-card" data-action="chain-stage" data-value="${x[0]}"><div class="stat-top">产业链环节 ${tag(x[0],i===1?'green':'')}</div><strong style="font-size:17px">${x[1]}</strong><p class="subtitle">${x[2]}</p><div style="margin-top:14px">${tag(x[3]+' 家关联企业','gray')} <span class="link">查看企业 →</span></div></div>`).join('')}</div>${card('产业链结构',`<div class="flow">${[['上游','设备制造 · 能源供应'],['中游','工程建设 · 系统集成'],['下游','城市运行 · 设施维护']].map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="flow-node" data-action="chain-stage" data-value="${x[0]}"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div>`)}${card('关联企业',table(['企业名称','所在城市','产业环节','招聘岗位','操作'],D.companies.slice(0,5).map((c,i)=>row([`<button class="link" data-action="company-open" data-value="${i}">${c}</button>`,['呼和浩特市','包头市','鄂尔多斯市'][i%3],tag(['上游','中游','下游'][i%3]),D.positions.filter(p=>p.company===c).length+' 个',`<button class="btn" data-action="company-open" data-value="${i}">查看详情</button>`]))))}`}
function jobs(){return `<div class="card"><div class="filters"><div class="field"><label>关键词</label><input id="job-search" placeholder="岗位名称 / 企业 / 能力"></div><div class="field"><label>城市</label><select id="job-city"><option value="">全部城市</option>${[...new Set(D.positions.map(p=>p.city))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>岗位群</label><select id="job-group"><option value="">全部岗位群</option>${[...new Set(D.positions.map(p=>p.group))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>学历</label><select id="job-edu"><option value="">全部</option><option>大专</option><option>本科</option></select></div><button class="btn primary" data-action="filter-jobs" style="align-self:end">查询岗位</button></div></div>${card('岗位列表',`<div id="jobs-table">${jobTable(D.positions)}</div>`,'演示岗位样本')}`}
function jobTable(list){return table(['岗位名称','招聘企业','岗位群','城市','薪资范围','学历','典型任务','操作'],list.map(p=>row([`<button class="link" data-action="job-open" data-value="${p.id}">${p.name}</button>`,`<button class="link" data-action="company-name" data-value="${safe(p.company)}">${p.company}</button>`,p.group,p.city,p.salary,p.edu,p.task,`<button class="btn" data-action="job-open" data-value="${p.id}">岗位溯源</button>`])))}
function jobDetail(){let p=D.positions.find(x=>x.id===S.selectedPosition)||D.positions[0];return `<div class="card"><div class="grid2"><div><span class="tag">${p.group}</span><h2>${p.name}</h2><div class="subtitle">${p.company} · ${p.city}</div><p style="margin-top:15px">面向城市生命线设施开展日常运行、设备巡检、故障排查与维护，依据安全规范记录运行数据并协助处置异常。</p>${tag('岗位需求 '+p.salary,'orange')}${tag(p.edu+' · '+p.exp,'gray')}</div><div><div class="subtitle">岗位能力画像（示意）</div>${p.skills.slice(0,5).map((s,i)=>`<div style="margin:12px 0"><div class="stat-top"><span>${s}</span><span>${92-i*9}%</span></div><div class="progress"><i style="width:${92-i*9}%"></i></div></div>`).join('')}</div></div></div><div class="grid2">${card('招聘记录',table(['招聘企业','工作地点','薪资','学历','经验'],[row([p.company,p.city,p.salary,p.edu,p.exp]),row([p.company,p.city,'7,000–12,000',p.edu,'1–3年'])]))}${card('能力要求',`<div class="task-row"><span class="tag orange">典型任务</span><b>${p.task}</b></div>${p.skills.map((s,i)=>`<div class="task-row"><span class="avatar" style="width:26px;height:26px">${i+1}</span><div style="flex:1"><b>${s}</b><div class="subtitle">岗位核心能力 · 权重 ${25-i*3}%</div></div><button class="link" data-action="goto-course">查看课程支撑 →</button></div>`).join('')}`)}</div>${card('岗位匹配专业与课程',`<div class="flow">${[['专业群',I.group],['专业',p.course.includes('电气')?'电气自动化技术':p.course.includes('供热')?'供热通风与空调工程技术':'建筑智能化工程技术'],['支撑课程',p.course],['能力要求',p.skills[0]]].map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="flow-node" data-route="${i===2?'standard-edit':'fourmap'}"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div>`)}<div class="head-actions">${btn('返回岗位库','jobs')} ${btn('查看能力图谱','fourmap','primary')}</div>`}
function company(){let name=S.companyName||D.companies[0];let ps=D.positions.filter(p=>p.company===name);return `${card('企业基本信息',`<h2>${name}</h2><p>区域城市运行与工程建设相关企业，开展设施运行维护、工程服务及技术支持。</p>${tag('内蒙古自治区','green')}${tag('关联岗位 '+ps.length+' 个','gray')}`)}${card('招聘岗位',jobTable(ps.length?ps:D.positions.slice(0,3)))}`}
function portal(){return `<div class="card"><span class="tag">${I.schools} · 专业群对接产业链全景</span><h2>${I.group}</h2><p>面向严寒地区城市生命线安全，服务供水、暖、电、气、安城市生命线系统。</p><div class="filters">${I.professionals.map((x,i)=>`<button class="btn ${i===0?'soft':''}" data-action="profession" data-value="${x}">${x}</button>`).join('')}</div><div class="stats">${stat('组群专业',5,'▤')}${stat('关联岗位群',4,'◉')}${stat('课程',D.courses.length,'▥')}${stat('典型任务',22,'⌘')}</div></div>${card('专业群搭建逻辑图',`<div class="flow">${[['产业图谱','10 个环节'],['岗位体系',D.positions.length+' 个岗位'],['专业群','5 个专业'],['课程体系',D.courses.length+' 门课程'],['任务体系','22 项任务']].map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="flow-node" data-route="${['chain','jobs','graph','course-jobs','tasks'][i]}"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div>`)}${card('培养体系与师资',`<div class="grid3"><div class="card"><b>培养目标</b><p class="subtitle">培养服务城市生命线运行的复合型技术技能人才。</p></div><div class="card"><b>实践教学</b><p class="subtitle">校内实训室、企业岗位实践、综合项目任务。</p></div><div class="card"><b>师资团队</b><p class="subtitle">专业教师与企业实践导师协同参与。</p></div></div>`)}`}
function fourmap(){let p=D.positions.find(x=>x.id===S.selectedPosition)||D.positions[0];return `<div class="filters"><div class="field"><label>岗位群</label><select id="map-pos">${[...new Set(D.positions.map(x=>x.group))].map(g=>`<option ${g===p.group?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>搜索岗位或能力</label><input id="map-search" placeholder="输入关键字"></div></div>${card('能力图谱四维映射',`<div class="flow">${[[p.group,'岗位群'],[p.name,'岗位'],[p.task,'能力模块 / 任务'],['能力要求','能力要求']].map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="flow-node" data-action="map-node" data-value="${x[0]}"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div>`)}<div class="grid2">${card('岗位能力要求',p.skills.map((s,i)=>`<div class="task-row"><span class="avatar" style="width:28px;height:28px">${i+1}</span><div style="flex:1"><b>${s}</b><div class="subtitle">${p.task} · 权重 ${25-i*3}%</div></div><button class="link" data-action="ability-courses" data-value="${s}">查看支撑课程</button></div>`).join(''))}${card('关联课程',D.courses.filter(c=>c.abilities.some(a=>p.skills.includes(a))).map(c=>`<div class="task-row"><div style="flex:1"><b>${c.name}</b><div class="subtitle">${c.major} · ${c.credits} 学分</div></div>${tag(c.status,'green')}<button class="btn" data-action="course-open" data-value="${c.id}">查看课程</button></div>`).join('')||'<div class="empty">选择能力节点查看课程</div>')}</div>${btn('打开课程岗位关联','course-jobs','primary')}`}
function graphPage(){let isSkills=S.active==='skills',isNet=S.active==='network';let chain=isSkills?['岗位群','岗位','典型任务','能力要求','技能点','知识群','课程']:isNet?['专业','岗位','任务','课程','能力项']:['产业链','产业','岗位','能力模块','能力要求','课程','专业'];let names=isSkills?['电气工程岗位群','电气设备运维工程师','配电设备巡检','故障诊断','异常识别与处理','电气故障知识','电气控制与PLC应用']:isNet?['电气自动化技术','电气设备运维工程师','配电设备巡检','电气控制与PLC应用','故障诊断']:['城市生命线智慧运行','设施运行维护','电气设备运维工程师','设备运行与维护','故障诊断','电气控制与PLC应用','电气自动化技术'];return `<div class="filters"><div class="field"><label>区域</label><select><option>内蒙古自治区</option><option>呼和浩特市</option></select></div><div class="field"><label>岗位群</label><select><option>全部岗位群</option>${[...new Set(D.positions.map(p=>p.group))].map(x=>`<option>${x}</option>`)}</select></div><div class="field"><label>视图</label><select id="graph-view"><option>图谱</option><option>表格</option></select></div></div><div class="stats">${stat('图谱节点',24,'◎')}${stat('关联关系',58,'⌘')}${stat('关联岗位',D.positions.length,'▤')}${stat('课程节点',D.courses.length,'▥')}</div>${card(isSkills?'知识技能映射链路图谱':isNet?'能力导向网络':'七层专业群能力图谱',`<div class="mini-map"><div class="flow">${chain.map((x,i)=>`${i?'<span class="arrow">⟶</span>':''}<div class="flow-node" data-action="graph-node" data-value="${names[i]}"><strong>${x}</strong><small>${names[i]}</small><small style="display:block;margin-top:5px">${i===0?'1 个':i===chain.length-1?'关联课程':'2 项关联'}　›</small></div>`).join('')}</div><div class="notice">点击节点查看关联详情；关系与岗位、课程示例数据保持一致。</div></div>`,'可点击节点')}<div class="grid2">${card('节点详情',`<b>${S.node||names[3]}</b><p class="subtitle">该节点连接岗位任务与课程教学内容，可在下方查看支撑关系。</p><button class="link" data-route="course-jobs">查看课程岗位关联 →</button>`)}${card('表格视图',table(['节点类型','节点名称','关联数量','操作'],chain.map((x,i)=>row([x,names[i],i===0?'1':i===chain.length-1?'1':'2',`<button class="link" data-action="graph-node" data-value="${names[i]}">查看</button>`]))))}</div>`}
function courseJobs(){let p=D.positions.find(x=>x.id===S.selectedPosition)||D.positions[0];let courseRows=D.courses.map(c=>row([`<button class="link" data-action="course-open" data-value="${c.id}">${c.name}</button>`,c.major,c.credits+' 学分',c.abilities.map(a=>tag(a,c.abilities.some(a=>p.skills.includes(a))?'green':'gray')).join(''),`<button class="btn" data-action="course-open" data-value="${c.id}">课程标准</button>`]));return `<div class="filters"><div class="field"><label>岗位</label><select id="course-pos">${D.positions.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="field"><label>专业</label><select><option>全部专业</option>${I.professionals.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>视图</label><select><option>矩阵</option><option>表格</option></select></div></div>${card('课程岗位支撑矩阵',`<div class="notice">当前岗位：<b>${p.name}</b>　核心能力：${p.skills.slice(0,3).join('、')}</div>${table(['课程','所属专业','学分','支撑能力','操作'],courseRows)}`)}${card('能力覆盖情况',`<div class="grid3">${p.skills.slice(0,3).map((a,i)=>`<div class="card"><div class="stat-top">${a}${tag(i===2?'待补强':'已覆盖',i===2?'orange':'green')}</div><div class="progress" style="margin:12px 0"><i style="width:${[90,82,48][i]}%"></i></div><button class="link" data-action="recommend" data-value="${a}">推荐支撑课程 →</button></div>`).join('')}</div>`)}${btn('打开课程能力推荐','recommend','primary')}`}
function recommend(){let c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];return `${card('课程能力推荐',`<div class="filters"><div class="field"><label>专业</label><select>${I.professionals.map(x=>`<option ${x===c.major?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>课程</label><select id="rec-course">${D.courses.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.name}</option>`).join('')}</select></div></div><div class="field"><label>提示词设置（演示）</label><textarea>结合岗位任务与现有课程内容，推荐课程应支撑的岗位能力。请给出能力项和简短理由。</textarea></div><div style="margin-top:12px">${btn('模拟生成推荐','generate-recommend','primary')}</div>`)}<div id="recommend-result">${S.recommendResult?recommendResult():''}</div>`}
function recommendResult(){let c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];let opts=[...new Set([...(c.abilities||[]),'故障诊断','运行数据分析','电气安全操作'])].slice(-3);return card('模拟推荐结果',`<div class="notice">根据课程内容与岗位任务生成，仅用于演示。</div>${opts.map((a,i)=>`<label class="task-row"><input class="check rec-check" type="checkbox" value="${a}" ${i<2?'checked':''}><span style="flex:1"><b>${a}</b><div class="subtitle">${i?'建议补充实训考核要求':'当前课程内容可支持该能力'}</div></span><span>${85-i*9}%</span></label>`).join('')}<div style="margin-top:14px">${btn('确认并更新映射','confirm-recommend','primary')}</div>`) }
function insight(){return `<div class="stats">${stat('产业链环节',10,'⌘')}${stat('关联企业',D.companies.length,'▣')}${stat('招聘岗位',D.positions.length,'▤')}${stat('产业技术热词',18,'✦')}</div><div class="grid2">${card('产业结构与环节',bars(['上游','中游','下游'],[42,67,83],true))}${card('产业需求趋势',lineChart(['2022','2023','2024','2025','2026'],[31,44,55,72,88]))}</div><div class="grid2">${card('区域需求分布 TOP5',bars(['呼和浩特','包头','鄂尔多斯','赤峰','乌兰察布'],[86,64,58,39,32],true))}${card('技术热词',`<div style="line-height:3">${['智慧运维','新能源','PLC控制','节能改造','城市生命线','楼宇自控','设备巡检','数字孪生'].map((x,i)=>`<button class="btn" data-action="keyword" data-value="${x}">${x}　${i+3}</button> `).join('')}</div>`)}</div>${card('典型岗位',jobTable(D.positions.slice(0,4)))}`}
function portrait(){let groups=[...new Set(D.positions.map(p=>p.group))];return `<div class="filters"><div class="field"><label>岗位群</label><select id="portrait-group">${groups.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="stats">${stat('岗位需求',128,'▤')}${stat('平均薪资','8,600','￥')}${stat('本科及以上','62%','⌂')}${stat('经验 1–3 年','54%','◷')}</div><div class="grid2">${card('能力要求画像',bars(['专业技能','设备维护','安全规范','数据分析','协同沟通'],[88,78,72,62,55],true))}${card('区域需求',bars(['呼和浩特','包头','鄂尔多斯','赤峰'],[80,58,45,28]))}</div>${card('岗位群岗位',jobTable(D.positions))}`}
function supply(){let approved=D.requirements.filter(x=>x.status==='已通过');let need=approved.reduce((n,x)=>n+x.count,0);let supplyCount=28;let allSkills=[...new Set(approved.flatMap(x=>Object.keys(x.weights||{})))];let supported=allSkills.filter(s=>D.courses.some(c=>c.abilities.includes(s))).length;let coverage=allSkills.length?Math.round(supported/allSkills.length*100):0;return `<div class="filters"><div class="field"><label>区域</label><select><option>内蒙古自治区</option><option>呼和浩特市</option></select></div><div class="field"><label>专业群</label><select><option>${I.group}</option></select></div><div class="field"><label>年度</label><select><option>2026</option><option>2025</option></select></div></div><div class="stats">${stat('已通过需求人数',need,'▤')}${stat('预计可供给人数',supplyCount,'◉')}${stat('人才人数缺口',Math.max(need-supplyCount,0),'↗')}${stat('能力覆盖率',coverage+'%','⌘')}</div><div class="grid2">${card('需求与供给对比',bars(['需求人数','预计供给','人数缺口'],[need,supplyCount,Math.max(need-supplyCount,0)],true))}${card('供需预警',`<div class="task-row"><span class="tag orange">人数缺口</span><div style="flex:1">${need> supplyCount?`当前样例需求短缺 ${need-supplyCount} 人`:'暂无人数缺口'}</div></div><div class="task-row"><span class="tag ${coverage<80?'orange':'green'}">能力覆盖</span><div style="flex:1">课程覆盖 ${coverage}%，${coverage<80?'建议补充课程支撑':'达到演示阈值'}</div></div><button class="link" data-route="course-jobs">查看能力与课程缺口 →</button>`)} </div>${card('企业需求明细',table(['企业','岗位','需求人数','优先级','状态','能力权重','操作'],D.requirements.map(x=>row([x.company,x.position,x.count,tag(x.priority,x.priority==='高'?'orange':''),tag(x.status,x.status==='已通过'?'green':'orange'),Object.keys(x.weights||{}).length+' 项',x.status==='待审核'?`<button class="btn primary" data-action="approve-demand" data-value="${x.id}">模拟通过</button>`:`<button class="link" data-action="demand-detail" data-value="${x.id}">查看</button>`]))))}${btn('填报企业需求','demand','primary')}`}
function demand(){let rows=D.requirements.map(x=>row([x.company,x.position,x.count,tag(x.priority,x.priority==='高'?'orange':''),tag(x.status,x.status==='已通过'?'green':x.status==='待审核'?'orange':'gray'),`<button class="btn" data-action="demand-detail" data-value="${x.id}">详情</button> ${x.status==='待审核'?`<button class="btn primary" data-action="approve-demand" data-value="${x.id}">模拟通过</button>`:''}`]));return `<div class="pill-tabs">${['全部','待审核','已通过','已驳回'].map(x=>`<button class="${S.demandTab===x?'active':''}" data-action="demand-tab" data-value="${x}">${x} <span class="tag">${x==='全部'?D.requirements.length:D.requirements.filter(d=>d.status===x).length}</span></button>`).join('')}</div>${card('需求填报表单',`<div class="notice">企业需求采用本地演示数据。提交后状态为待审核，经管理员模拟通过后计入供需看板。</div>${table(['企业名称','需求岗位','人数','优先级','状态','操作'],D.requirements.filter(x=>S.demandTab==='全部'||x.status===S.demandTab).map(x=>row([x.company,x.position,x.count,tag(x.priority),tag(x.status,x.status==='已通过'?'green':'orange'),x.status==='待审核'?`<button class="btn primary" data-action="approve-demand" data-value="${x.id}">模拟通过</button>`:'已计入看板'])))}`)}<div class="head-actions">${btn('新增企业需求','demand-new','primary')}</div>`}
function plans(){return `${card('培养方案列表',table(['方案名称','专业','年级','当前版本','状态','操作'],D.plans.map(x=>row([`<button class="link" data-action="plan-preview" data-value="${x.id}">${x.name}</button>`,x.major,x.year,x.version,tag(x.status,'green'),`<button class="btn" data-action="plan-preview" data-value="${x.id}">预览</button> <button class="btn" data-route="versions">版本管理</button> <button class="btn" data-route="review">动态修订</button>`]))))}${card('培养方案研制',`<div class="grid3">${[['plan-new','新制定培养方案','基于知识库或模板创建方案'],['plan-config','配置工作台','配置模板、提示词与硬规则'],['library','研制知识库','管理方案资料与解析状态']].map(x=>`<div class="card module-card" data-route="${x[0]}"><span class="tag">研制</span><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('')}</div>`)}`}
function planNew(){let step=S.planStep||0;let steps=['选择起点','填写信息','查看结果','章节匹配'];return `${card('新制定培养方案',`<div class="timeline">${steps.map((x,i)=>`<div class="step ${i===step?'active':i<step?'done':''}">${i+1}　${x}</div>`).join('')}</div>${step===0?`<h3>选择新方案来源</h3><div class="grid2"><div class="card module-card" data-action="plan-source" data-value="知识库既有方案"><b>从知识库既有方案新建</b><p>保留课程与能力关联，基于现有资料生成方案草稿。</p></div><div class="card module-card" data-action="plan-source" data-value="标准模板"><b>从标准模板新建</b><p>按专业群模板生成章节结构与培养要求。</p></div></div><div class="field"><label>原方案资料</label><select id="plan-source-select"><option>2026级供热通风与空调工程技术专业人才培养方案</option><option>专业群培养方案标准模板</option></select></div>`:step===1?`<div class="grid2"><div class="field"><label>方案名称 *</label><input id="plan-name" value="${safe(S.planDraft.name||'2027级供热通风与空调工程技术专业人才培养方案')}"></div><div class="field"><label>专业</label><select id="plan-major">${I.professionals.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>年级</label><input id="plan-year" value="2027级"></div><div class="field"><label>学制</label><select><option>三年制</option><option>五年制</option></select></div></div>`:step===2?`<div class="notice">模拟生成已完成。请检查方案概要后继续章节匹配。</div>${['培养目标','毕业要求','课程体系','实践教学'].map(x=>`<div class="task-row"><b>${x}</b><span style="margin-left:auto">已生成</span>${tag('来源可追溯','green')}</div>`).join('')}`:`<div class="notice">章节匹配完成后创建方案草稿。点击章节可调整来源。</div>${['专业人才需求调研','培养目标与毕业要求','课程设置与学时分配','实践教学体系'].map(x=>`<div class="task-row"><input type="checkbox" class="check" checked><b style="flex:1">${x}</b><select><option>已匹配 · 知识库资料</option><option>手动补充</option></select></div>`).join('')}`}<div class="head-actions" style="margin-top:16px">${step?btn('上一步','plan-prev'):''}${step<3?btn('下一步：'+steps[step+1],'plan-next','primary'):btn('创建培养方案','plan-create','primary')}</div>`,'四步研制流程')}`}
function planPreview(){let p=D.plans.find(x=>x.id===S.planId)||D.plans[0];return `<div class="head-actions" style="margin-bottom:14px">${btn('返回方案管理','plans')} ${btn('版本管理','versions')} ${btn('下载方案','download-plan','primary')}</div>${card('方案信息',`<div class="grid3"><div><small class="subtitle">方案名称</small><b style="display:block">${p.name}</b></div><div><small class="subtitle">适用专业</small><b style="display:block">${p.major}</b></div><div><small class="subtitle">状态 / 版本</small><b style="display:block">${p.status} · ${p.version}</b></div></div>`)}<div class="report-paper"><h2>${p.name}</h2><p>为服务内蒙古城市生命线运行与工程建设产业发展，结合岗位需求和专业群能力图谱，制定本培养方案。</p><h3>一、专业人才培养目标</h3><p>培养掌握专业基础知识和岗位核心技能，能够从事设备运行维护、工程实施、系统调试及安全管理的高素质技术技能人才。</p><h3>二、职业面向</h3><p>主要面向电气设备运维、暖通系统运行、建筑智能化、给排水设施维护等岗位。</p><h3>三、课程体系</h3>${table(['课程名称','学分','学期','支撑岗位能力'],D.courses.slice(0,5).map(c=>row([c.name,c.credits,c.term,c.abilities.slice(0,2).join('、')])))}</div>`}
function versions(){return `${card('版本管理',table(['版本','更新时间','版本说明','状态','操作'],[{v:'V2.0',t:'2026-11-25',d:'补充设备运维能力与实训课程',s:'当前版本'},{v:'V1.0',t:'2026-06-18',d:'专业群初版培养方案',s:'历史版本'}].map(x=>row([x.v,x.t,x.d,tag(x.s,x.s==='当前版本'?'green':'gray'),`<button class="link" data-action="compare">选择对比</button>`]))))}${card('版本差异对比',`<div class="notice">选择两个版本后展示方案内容差异。</div>${table(['字段','V1.0','V2.0','变更'],[row(['课程支撑能力','基础电气操作','增加故障诊断、运行数据分析',tag('已调整','orange')]),row(['实践课程','4 门','5 门',tag('新增 1 门','green')]),row(['企业岗位需求','2025 年数据','2026 年数据',tag('已更新','green')])])}`)}`}
function standards(){return `${card('课程统计',`<div class="stats">${stat('课程总数',D.courses.length,'▥')}${stat('已编制',D.courses.filter(c=>c.status==='已编制').length,'✓')}${stat('待编制',D.courses.filter(c=>c.status==='待编制').length,'◷')}${stat('关联能力',new Set(D.courses.flatMap(c=>c.abilities)).size,'⌘')}</div>`)}<div class="filters"><div class="field"><label>专业</label><select><option>全部专业</option>${I.professionals.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>编制状态</label><select><option>全部状态</option><option>已编制</option><option>待编制</option></select></div><div class="field"><label>关键词</label><input placeholder="课程名称"></div></div>${card('课程标准清单',table(['课程名称','所属专业','学分','开课学期','编制状态','能力要素','操作'],D.courses.map(c=>row([`<button class="link" data-action="course-open" data-value="${c.id}">${c.name}</button>`,c.major,c.credits,c.term,tag(c.status,c.status==='已编制'?'green':'orange'),`${c.abilities.length} 项`,`<button class="btn primary" data-action="course-open" data-value="${c.id}">${c.status==='已编制'?'查看 / 编辑':'开始编制'}</button>`]))))}`}
function standardEdit(){let c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];let sections=['课程信息','课程性质与定位','课程目标与内容','课程考核与评价','实施要求','参考附件'];return `<div class="head-actions" style="margin-bottom:14px">${btn('返回课程标准','standards')} ${btn('保存课程标准','save-standard','primary')}</div>${card(c.name,`<div class="notice">${c.major} · ${c.credits} 学分 · ${c.term} · ${tag(c.status,c.status==='已编制'?'green':'orange')}</div><div class="split"><div class="tree-list">${sections.map((x,i)=>`<div class="tree-item ${i===0?'active':''}" data-action="standard-section" data-value="${i}">${i+1}. ${x}</div>`).join('')}</div><div><div class="field"><label>课程目标与内容</label><textarea id="standard-text">${safe(c.standardText||`通过本课程学习，学生能够掌握${c.abilities.join('、')}等知识与技能，完成${D.positions.find(p=>p.course===c.name)?.task||'相关岗位典型工作任务'}，具备规范操作、安全作业和协同沟通能力。`)}</textarea></div><div class="card-title" style="margin-top:16px">课程教学目标</div>${table(['序号','项目模块','知识目标','能力目标','操作'],[['1','基础理论','掌握专业基础知识','能完成基本操作','删除'],['2','岗位实践','理解典型工作任务','具备综合应用能力','删除']].map((x,i)=>row([x[0],`<input value="${x[1]}" style="width:100px">`,`<input value="${x[2]}" style="width:140px">`,`<input value="${x[3]}" style="width:140px">`,`<button class="link" data-action="delete-row">删除</button>`])))}<button class="btn" style="margin-top:8px" data-action="add-row">＋ 添加一行</button><div style="margin-top:18px">${btn('AI 补充本节（模拟）','ai-standard','soft')}</div></div></div>`,'六章课程要素 · 所有更改可保存')}`}
function library(){let assets=[['人才培养方案示例','培养方案','已解析',12],['城市生命线岗位需求调研','调研资料','已解析',8],['电气设备运维岗位标准','行业标准','已解析',6],['课程标准模板','课程资料','已解析',9],['企业招聘岗位样本','招聘数据','待解析',0]];return `<div class="filters"><div class="field"><label>资料类型</label><select><option>全部类型</option><option>培养方案</option><option>行业标准</option></select></div><div class="field"><label>解析状态</label><select><option>全部状态</option><option>已解析</option><option>待解析</option></select></div><div class="field"><label>关键词</label><input placeholder="搜索资料名称"></div><label class="btn primary" style="align-self:end">上传资料（模拟）<input type="file" id="file-upload" class="hidden"></label></div>${card('知识库资料',table(['资料名称','资料类型','状态','解析元素','更新时间','操作'],assets.map((x,i)=>row([`<button class="link" data-route="doc-preview">${x[0]}</button>`,tag(x[1]),tag(x[2],x[2]==='已解析'?'green':'orange'),x[3]+' 项','2026-11-'+(25-i),`<button class="btn" data-route="doc-preview">预览</button>`]))),'演示资料样本')}`}
function reports(){return `<div class="pill-tabs">${['我的报告','已发布报告'].map(x=>`<button class="${S.reportTab===x?'active':''}" data-action="report-tab" data-value="${x}">${x}</button>`).join('')}</div>${card('产业链洞察报告',table(['报告名称','报告范围','状态','更新时间','操作'],D.reports.filter(x=>S.reportTab==='我的报告'||x.status==='已发布').map(x=>row([`<button class="link" data-action="report-open" data-value="${x.id}">${x.name}</button>`,x.scope,tag(x.status,x.status==='已发布'?'green':'orange'),x.updated,`<button class="btn primary" data-action="report-open" data-value="${x.id}">编辑 / 预览</button>`]))),'我的报告 · '+D.reports.length+' 份')}${card('报告创建',`<div class="grid3"><div class="card module-card" data-action="new-report"><b>新建产业链洞察报告</b><p>选择模板和分析范围，生成报告草稿。</p></div><div class="card module-card" data-route="templates"><b>AI 报告模板</b><p>管理报告目录与数据范围。</p></div><div class="card module-card" data-route="tasks"><b>典型工作任务</b><p>查看岗位任务与课程支撑。</p></div></div>`)}`}
function reportEdit(){let r=D.reports.find(x=>x.id===S.editingReport)||D.reports[0];return `<div class="head-actions" style="margin-bottom:12px">${btn('报告设置','report-settings')} ${btn('保存版本','save-report')} ${btn('生成本节（模拟）','generate-section','soft')} ${btn('生成全文（模拟）','generate-report','primary')} ${btn('发布报告','publish-report','primary')}</div><div class="split"><div class="card"><b>报告目录</b>${['执行摘要','专业群概况','上游产业链分析','中游产业链分析','下游产业链分析','产业链整体分析','结论与专业建设建议'].map((x,i)=>`<div class="tree-item ${i===0?'active':''}" data-action="report-section" data-value="${x}">${x}</div>`).join('')}<div class="progress" style="margin:14px 0"><i style="width:72%"></i></div><small class="subtitle">完成度 72%</small></div><div class="card"><div class="stat-top"><b>${r.name}</b>${tag('演示数据')}</div><div class="field" style="margin-top:14px"><label>执行摘要</label><textarea id="report-content" style="min-height:360px">${safe(S.reportContent||r.content||'本报告面向内蒙古自治区城市生命线智慧运行相关专业群，围绕产业链企业与岗位需求开展分析。样例数据显示，区域岗位需求主要集中在设备运行维护、系统调试与安全管理方向。\n\n专业群现有课程能够支撑电气安全操作、PLC控制和设备维护等核心能力。部分岗位提出的运行数据分析与故障诊断要求，仍需通过课程内容优化和实践项目补充。\n\n建议结合企业岗位需求变化，完善课程岗位映射，强化真实任务训练，并持续跟踪企业需求与人才供给情况。')}</textarea></div><div class="notice">引用数据：岗位样本 ${D.positions.length} 个 · 课程 ${D.courses.length} 门 · 企业需求 ${D.requirements.length} 条</div></div></div>`}
function templates(){return `${card('报告模板列表',table(['模板名称','模板编码','章节数','状态','操作'],D.templates.map(t=>row([t.name,t.id.toUpperCase(),'7',tag(t.enabled?'启用':'停用',t.enabled?'green':'gray'),`<button class="btn" data-action="toggle-template" data-value="${t.id}">${t.enabled?'停用':'启用'}</button> <button class="btn" data-route="template-edit">配置</button>`]))))}${card('模板配置预览',`<div class="pill-tabs">${['基础信息','关联参数','报告目录','内部数据','生成设置'].map((x,i)=>`<button class="${i===0?'active':''}" data-action="template-tab">${x}</button>`).join('')}</div><div class="grid2"><div class="field"><label>模板名称</label><input id="template-name" value="产业链洞察报告模板"></div><div class="field"><label>模板编码</label><input value="chain-insight-report"></div><div class="field"><label>报告说明</label><input value="面向专业群的产业链岗位需求调研分析"></div></div><div style="margin-top:12px">${btn('保存模板配置','save-template','primary')}</div>`)}`}
function forecast(){return `<div class="filters"><div class="field"><label>区域</label><select><option>内蒙古自治区</option>${['呼和浩特市','包头市'].map(x=>`<option>${x}</option>`)}</select></div><div class="field"><label>岗位群</label><select><option>全部岗位群</option>${[...new Set(D.positions.map(p=>p.group))].map(x=>`<option>${x}</option>`)}</select></div>${btn('运行需求预测（模拟）','run-forecast','primary')}</div><div id="forecast-output">${S.forecast?forecastOutput():card('预测说明','<div class="empty">设置区域与岗位群后点击运行预测，查看预设趋势结果。</div>')}</div>`}
function forecastOutput(){return `<div class="stats">${stat('预测岗位需求','+18%','↗')}${stat('高需求岗位','4','▤')}${stat('预测周期','未来 12 个月','◷')}${stat('数据来源','模拟样本','▧')}</div>${card('需求指数趋势',lineChart(['2025 Q1','Q2','Q3','Q4','2026 Q1','Q2'],[42,48,53,65,74,88]))}${card('需求预测 TOP10',jobTable(D.positions.slice(0,5)))}`}
function emerging(){return `${card('新兴岗位展望',`<div class="notice">依据产业动态和招聘趋势整理的演示样例，点击生成可查看模拟结果。</div><div class="grid3">${[['城市生命线数字运维专员','智慧运维 · 数据分析'],['新能源场站电气调试员','新能源 · PLC控制'],['建筑能效管理工程师','节能改造 · 能耗分析']].map(x=>`<div class="card"><span class="tag green">新兴岗位</span><h3>${x[0]}</h3><p class="subtitle">能力标签：${x[1]}</p><button class="link" data-action="emerging-detail" data-value="${x[0]}">查看岗位画像 →</button></div>`).join('')}</div>${btn('生成新兴岗位（模拟）','generate-emerging','primary')}`)}`}
function news(){let types=['政策文件','行业标准','技术白皮书','产业报告','招聘数据'];let items=[['城市生命线安全工程建设指导意见','行业主管部门','2026-10-18','政策更新'],['建筑设备运行维护岗位能力标准','行业协会','2026-09-03','岗位变化'],['新能源运维技能人才需求分析','研究机构','2026-08-21','需求增长']];return `<div class="pill-tabs">${types.map((x,i)=>`<button class="${(S.newsTab||types[0])===x?'active':''}" data-action="news-tab" data-value="${x}">${x}</button>`).join('')}</div>${card((S.newsTab||types[0])+' · 前沿动态',table(['资料标题','发布机构','日期','标签','操作'],items.map(x=>row([x[0],x[1],x[2],tag(x[3]),`<button class="btn" data-action="preview-news" data-value="${x[0]}">查看预览</button>`]))))}`}
function lightPage(){let id=S.active,title=getTitle(id);let descriptions={'matrix-types':'按岗位群与岗位类型浏览岗位矩阵，点击岗位查看岗位画像。','major-jobs':'查看专业与岗位群的覆盖关系，点击单元格查看关联岗位。','embed':'预览图谱并生成演示用嵌入代码或下载 SVG。','tasks':'从岗位进入典型工作任务，再查看能力要求和课程支撑。','research':'查看专业调研报告目录、证据来源与分析结论。','plan-config':'配置培养方案模块、模板提示词与演示硬规则。','review':'查看岗位能力变化形成的培养方案动态修订建议。','admin-nav':'管理演示导航与管理员操作。'};let extra=id==='embed'?`${btn('复制演示嵌入代码','copy-embed','soft')} ${btn('下载 SVG 图谱','download','primary')}`:id==='review'?`${btn('运行动态审议（模拟）','run-review','primary')} ${btn('查看培养方案版本','versions')}`:id==='plan-config'?btn('保存配置','save-config','primary'):'';return `${card(title,`<div class="notice">${descriptions[id]||'此功能保留了核心信息结构，可通过下方入口继续查看关联数据。'}</div><div class="grid3">${[['graph','能力图谱','查看产业、岗位、能力和课程节点'],['course-jobs','课程岗位关联','查看能力项对应课程'],['supply','供需匹配看板','查看需求与供给差距']].map(x=>`<div class="card module-card" data-route="${x[0]}"><b>${x[1]}</b><p>${x[2]}</p></div>`).join('')}</div>${extra}<div style="margin-top:12px">${btn('查看相关岗位','jobs')} ${btn('查看课程标准','standards')} ${btn('返回总览','home','primary')}</div>`)}${card('关联信息',table(['对象','信息','操作'],[[`岗位样本`,D.positions.length+' 个',`<button class="link" data-route="jobs">打开</button>`],[`专业群`,I.group,`<button class="link" data-route="portal">打开</button>`],[`课程`,D.courses.length+' 门',`<button class="link" data-route="standards">打开</button>`]].map(x=>row(x))))}`}
function modal(){let m=S.modal;let body='';if(m==='new-report')body=`<div class="field"><label>报告名称</label><input id="new-report-name" value="城市生命线智慧运行产业链调研报告"></div><div class="field" style="margin-top:12px"><label>报告模板</label><select id="new-report-template">${D.templates.filter(t=>t.enabled).map(t=>`<option>${t.name}</option>`).join('')}</select></div><div class="grid2" style="margin-top:12px"><div class="field"><label>区域</label><select><option>内蒙古自治区</option></select></div><div class="field"><label>年度</label><select><option>2026</option><option>2025</option></select></div></div><div class="field" style="margin-top:12px"><label>专业群</label><select><option>${I.group}</option></select></div>`;
else if(m==='demand-new')body=`<div class="notice">带 * 项为必填。能力权重合计需为 100%，该表单只保存到本地演示数据。</div><div class="grid2"><div class="field"><label>企业名称 *</label><select id="d-company">${D.companies.map(x=>`<option>${x}</option>`).join('')}<option value="custom">手动填写</option></select></div><div class="field"><label>需求岗位 *</label><select id="d-position">${D.positions.map(x=>`<option>${x.name}</option>`).join('')}</select></div><div class="field"><label>需求人数 *</label><input id="d-count" type="number" min="1" value="20"></div><div class="field"><label>优先级</label><select id="d-priority"><option>高</option><option>中</option><option>低</option></select></div></div><div class="field" style="margin-top:12px"><label>岗位能力权重（总和 100%）</label><div class="grid3">${['电气安全操作','故障诊断','PLC控制','设备维护'].map((x,i)=>`<div class="field"><label>${x}</label><input class="d-weight" value="${[30,25,25,20][i]}" type="number"></div>`).join('')}</div></div>`;
else if(m==='admin')body=`<p>当前为本地演示身份：管理员 · ${I.schools}</p><div class="notice">清除本地修改后，页面恢复到初始示例数据。</div>${btn('重置演示数据','reset-data','danger')} ${btn('退出登录','logout')}`;
else if(m==='demand-detail'){let d=D.requirements.find(x=>x.id===S.modalValue);body=d?`<h3>${d.position}</h3><p>${d.company} · 需求 ${d.count} 人 · ${d.priority}优先级 · ${d.status}</p>${Object.entries(d.weights||{}).map(([k,v])=>`<div class="task-row"><span style="flex:1">${k}</span><b>${v}%</b></div>`).join('')}`:'需求记录不存在';}
else if(m==='company-list')body=`<p>产业环节：${S.modalValue||'下游'}</p>${jobTable(D.positions)}`;
else if(m==='preview')body=`<div class="notice">${safe(S.modalValue||'')} · 演示资料预览</div><h3>资料摘要</h3><p>本资料用于支持专业群产业调研和人才培养方案研制，演示环境仅展示预设摘要与目录。</p><div class="task-row">资料来源　　行业/政策公开资料（演示）</div><div class="task-row">关联主题　　岗位需求、能力要求、课程建设</div>`;
else body=`<div class="notice">${safe(m)} · 演示交互</div><p>已打开对应操作窗口，可查看相关信息或继续进入完整页面。</p>`;
return `<div class="modal-backdrop" data-action="backdrop"><div class="modal"><div class="modal-head">${({ 'new-report':'新建产业链洞察报告','demand-new':'新增企业岗位需求',admin:'管理员菜单','demand-detail':'企业需求详情','company-list':'关联企业',preview:'资料预览'}[m]||'操作面板')}<button data-action="close-modal">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${btn('取消','close-modal')} ${m==='new-report'?btn('创建报告','create-report','primary'):m==='demand-new'?btn('提交需求','submit-demand','primary'):m==='company-list'?btn('查看岗位','jobs','primary'):btn('关闭','close-modal','primary')}</div></div></div>`}
function bind(){document.querySelectorAll('[data-route]').forEach(n=>n.addEventListener('click',()=>go(n.dataset.route)));document.querySelectorAll('[data-action]').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();action(n.dataset.action,n.dataset.value,n)}));document.querySelectorAll('[data-action="backdrop"]').forEach(n=>n.addEventListener('click',e=>{if(e.target===n){S.modal=null;render()}}));const up=el('file-upload');if(up)up.addEventListener('change',()=>{let f=up.files[0];if(f){toast(`已选择 ${f.name}，模拟解析中…`);setTimeout(()=>{toast('模拟解析完成，资料已加入知识库');},900)}});let txt=el('report-content');if(txt)txt.addEventListener('input',()=>S.reportContent=txt.value);let select=el('rec-course');if(select)select.addEventListener('change',()=>{S.selectedCourse=select.value;S.recommendResult=false;render()});let pselect=el('course-pos');if(pselect)pselect.addEventListener('change',()=>{S.selectedPosition=pselect.value;go('course-jobs')});let map=el('map-pos');if(map)map.addEventListener('change',()=>{let p=D.positions.find(x=>x.group===map.value);if(p){S.selectedPosition=p.id;go('fourmap')}});let gview=el('graph-view');if(gview)gview.addEventListener('change',()=>toast('已切换为'+gview.value+'视图'));}
function action(a,v,node){switch(a){
case'sidebar':S.sidebar=!S.sidebar;render();break;case'toggle-nav-group':S.collapsedNav[v]=!S.collapsedNav[v];render();break;case'admin':S.modal='admin';render();break;case'close-modal':S.modal=null;render();break;case'backdrop':break;case'logout':S.modal=null;go('login');break;case'login-submit':if(!el('login-user')?.value||!el('login-pass')?.value)toast('请输入演示账号和密码');else{toast('登录成功');go('home')}break;
case'refresh':toast('数据已刷新');break;case'reset-filter':document.querySelectorAll('.filters input').forEach(x=>x.value='');document.querySelectorAll('.filters select').forEach(x=>x.selectedIndex=0);toast('筛选条件已重置');break;
case'jobs':case'home':case'plans':case'demand':case'supply':case'graph':case'fourmap':case'course-jobs':case'reports':case'standards':case'portal':go(a);break;
case'chain-stage':S.modal='company-list';S.modalValue=v;render();break;case'company-open':S.companyName=D.companies[Number(v)]||D.companies[0];go('company');break;case'company-name':S.companyName=v;go('company');break;
case'job-open':S.selectedPosition=v;go('jobdetail');break;case'goto-course':go('fourmap');break;case'course-open':S.selectedCourse=v;go('standard-edit');break;
case'filter-jobs':{let q=(el('job-search')?.value||'').toLowerCase(),city=el('job-city')?.value||'',group=el('job-group')?.value||'',edu=el('job-edu')?.value||'';let list=D.positions.filter(p=>(!q||[p.name,p.company,...p.skills].join(' ').toLowerCase().includes(q))&&(!city||p.city===city)&&(!group||p.group===group)&&(!edu||p.edu===edu));el('jobs-table').innerHTML=jobTable(list);bind();toast(`找到 ${list.length} 个岗位`);break;}
case'graph-node':S.node=v;render();break;case'map-node':S.node=v;toast('已选中节点：'+v);break;case'ability-courses':S.node=v;go('course-jobs');break;
case'generate-recommend':S.recommendResult=true;S.selectedCourse=el('rec-course')?.value||S.selectedCourse;render();break;case'confirm-recommend':{let checks=[...document.querySelectorAll('.rec-check:checked')].map(x=>x.value),c=D.courses.find(x=>x.id===S.selectedCourse);if(c){c.abilities=[...new Set([...c.abilities,...checks])];persist();toast('能力关联已更新，可在课程岗位矩阵查看');go('course-jobs')}break;}
case'profession':toast('已切换展示专业：'+v);break;case'keyword':S.active='jobs';render();if(el('job-search'))el('job-search').value=v;break;
case'demand':go('demand');break;case'demand-new':S.modal='demand-new';render();break;case'demand-tab':S.demandTab=v;render();break;case'demand-detail':S.modal='demand-detail';S.modalValue=v;render();break;case'approve-demand':{let d=D.requirements.find(x=>x.id===v);if(d){d.status='已通过';persist();toast('需求已模拟审核通过，并计入供需看板');render()}break;}
case'submit-demand':{let count=Number(el('d-count')?.value),weights=[...document.querySelectorAll('.d-weight')].map(x=>Number(x.value)||0),sum=weights.reduce((a,b)=>a+b,0);if(!Number.isInteger(count)||count<1){toast('请输入大于 0 的整数人数');break}if(sum!==100){toast('能力权重合计需为 100%');break}let company=el('d-company').value,position=el('d-position').value;D.requirements.unshift({id:'d'+Date.now(),company,position,count,priority:el('d-priority').value,status:'待审核',weights:Object.fromEntries(['电气安全操作','故障诊断','PLC控制','设备维护'].map((x,i)=>[x,weights[i]]))});persist();S.modal=null;toast('需求已提交，等待管理员审核');render();break;}
case'new':if(S.active==='demand'){S.modal='demand-new';render()}else if(S.active==='reports'){S.modal='new-report';render()}else if(S.active==='plans')go('plan-new');else if(S.active==='library')toast('点击上传资料可选择本地文件并模拟解析');break;
case'new-report':S.modal='new-report';render();break;case'create-report':{let name=el('new-report-name').value.trim()||'未命名报告';let r={id:'r'+Date.now(),name,scope:'内蒙古自治区 · 2026年',status:'草稿',updated:'2026-11-25'};D.reports.unshift(r);persist();S.editingReport=r.id;S.reportContent='';S.modal=null;toast('报告草稿已创建');go('report-edit');break;}
case'plan-new':go('plan-new');break;case'plan-next':if((S.planStep||0)===0)S.planSource=el('plan-source-select')?.value||'知识库既有方案';if(S.planStep===1)S.planDraft={name:el('plan-name')?.value,major:el('plan-major')?.value,year:el('plan-year')?.value};S.planStep=Math.min((S.planStep||0)+1,3);render();break;case'plan-prev':if(S.planStep===2)S.planDraft={name:el('plan-name')?.value,major:el('plan-major')?.value,year:el('plan-year')?.value};S.planStep=Math.max((S.planStep||0)-1,0);render();break;case'plan-source':S.planSource=v;document.querySelectorAll('[data-action="plan-source"]').forEach(x=>x.classList.toggle('active',x.dataset.value===v));toast('已选择方案来源：'+v);break;case'plan-create':{let name=el('plan-name')?.value||S.planDraft.name||'2027级专业人才培养方案',major=el('plan-major')?.value||S.planDraft.major||I.professionals[0],year=el('plan-year')?.value||'2027级';let p={id:'pl'+Date.now(),name,major,year,status:'草稿',version:'V1.0'};D.plans.unshift(p);persist();S.planId=p.id;S.planStep=0;toast('培养方案草稿已创建');go('plan-preview');break;}
case'plan-preview':S.planId=v||D.plans[0].id;go('plan-preview');break;case'compare':toast('已加载 V1.0 与 V2.0 字段差异');break;case'download-plan':download('培养方案演示.txt',`${D.plans.find(x=>x.id===S.planId)?.name||'培养方案'}\n\n培养目标：面向产业岗位需求培养高素质技术技能人才。`,'text/plain');break;
case'course-jobs':go('course-jobs');break;case'save-standard':{let c=D.courses.find(x=>x.id===S.selectedCourse);if(c){c.standardText=el('standard-text').value;c.status='已编制';persist();toast('课程标准已保存');render()}break;}case'ai-standard':el('standard-text').value+='\n\n（模拟 AI 建议）结合岗位典型任务增加设备故障诊断、安全规范操作与综合实训考核内容。';toast('已填入模拟建议，请检查后保存');break;case'add-row':toast('已新增课程目标行');break;case'delete-row':node.closest('tr')?.remove();toast('已删除该行');break;case'standard-section':document.querySelectorAll('.tree-item').forEach(x=>x.classList.remove('active'));node.classList.add('active');toast('已定位到章节：'+v);break;
case'report-open':S.editingReport=v;S.reportContent='';go('report-edit');break;case'report-tab':S.reportTab=v;render();break;case'save-report':{let r=D.reports.find(x=>x.id===S.editingReport);if(r){r.content=el('report-content').value;r.updated='2026-11-25';if(r.status==='已发布')r.status='草稿';persist();toast('报告版本已保存')}break;}case'generate-section':case'generate-report':{let box=el('report-content');box.value+=`\n\n（模拟生成）${a==='generate-section'?'本节':'报告'}根据当前专业群、岗位与课程演示数据生成。当前样本包含 ${D.positions.length} 个岗位、${D.courses.length} 门课程与 ${D.requirements.length} 条企业需求。建议持续跟踪企业能力要求变化，补充课程实训内容并复核岗位能力覆盖情况。`;S.reportContent=box.value;toast('模拟生成完成，请检查内容与数据来源');break;}case'publish-report':{let r=D.reports.find(x=>x.id===S.editingReport);if(r){r.content=el('report-content').value;r.status='已发布';persist();toast('报告已发布到演示列表')}break;}case'report-settings':toast('报告范围：内蒙古自治区 · 2026 年 · '+I.group);break;case'report-section':toast('已定位章节：'+v);break;
case'toggle-template':{let t=D.templates.find(x=>x.id===v);t.enabled=!t.enabled;persist();render();toast(t.enabled?'模板已启用':'模板已停用');break;}case'save-template':{let n=el('template-name').value.trim();if(n){D.templates[0].name=n;persist();toast('模板配置已保存')}break;}case'template-tab':document.querySelectorAll('.pill-tabs button').forEach(x=>x.classList.remove('active'));node.classList.add('active');toast('已切换配置项');break;
case'run-forecast':S.forecast=true;render();toast('需求预测已完成（模拟结果）');break;case'generate-emerging':toast('已生成 2 个模拟新兴岗位');break;case'emerging-detail':S.modal='preview';S.modalValue=v;render();break;case'news-tab':S.newsTab=v;render();break;case'preview-news':S.modal='preview';S.modalValue=v;render();break;
case'reset-data':if(confirm('确定恢复初始演示数据？本地修改将被清除。')){localStorage.removeItem('nm-demo-data');D=structuredClone(I);S=initial();persist();render();toast('演示数据已重置')}break;
case'copy-embed':navigator.clipboard?.writeText('<iframe src="./#graph" title="专业群能力图谱演示"></iframe>').then(()=>toast('演示嵌入代码已复制')).catch(()=>toast('演示代码：<iframe src="./#graph"></iframe>'));break;case'run-review':toast('动态审议完成：建议补充故障诊断与运行数据分析实训');break;case'save-config':persist();toast('演示配置已保存');break;
case'download':download('图谱演示.svg','<svg xmlns="http://www.w3.org/2000/svg" width="700" height="160"><rect width="100%" height="100%" fill="#f7f9fc"/><text x="24" y="50" font-family="sans-serif" font-size="18">专业群能力图谱 · 演示导出</text><text x="24" y="100" font-family="sans-serif" font-size="14">产业 → 岗位 → 能力 → 课程 → 专业</text></svg>','image/svg+xml');break;
default:if(FEATURE_IDS.includes(a))go(a);else toast('演示交互：'+a);
}}
function download(name,content,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);toast('文件已下载')}
document.addEventListener('click',e=>{let n=e.target.closest('[data-route]');if(n&&n.dataset.route==='admin-nav'){S.modal='admin';render()}});
if(location.hash&&FEATURE_IDS.includes(location.hash.slice(1))){S.active=location.hash.slice(1);let g=NAV.find(x=>x.items.some(item=>item[0]===S.active));if(g)S.collapsedNav[g.group]=false}render();

